package com.example.json;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/**
 * Shared JSON entry point. {@link JsonMapper} is immutable and thread-safe,
 * so a single instance can be reused across the application.
 */
public final class Json {

    private static final JsonMapper MAPPER = JsonMapper.builder().build();

    private Json() {
    }

    public static JsonMapper mapper() {
        return MAPPER;
    }

    public static String toJson(Object value) {
        return MAPPER.writeValueAsString(value);
    }

    public static String toPrettyJson(Object value) {
        return MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(value);
    }

    public static <T> T fromJson(String json, Class<T> type) {
        return MAPPER.readValue(json, type);
    }

    public static JsonNode parseTree(String json) {
        return MAPPER.readTree(json);
    }
}
EOF
cat > src/main/java/com/example/json/App.java <<'EOF'
package com.example.json;

import java.util.List;

import tools.jackson.databind.JsonNode;

public class App {

    public static void main(String[] args) {
        Person alice = new Person("Alice", 30, List.of("admin", "dev"));

        String json = Json.toPrettyJson(alice);
        System.out.println("Generated:\n" + json);

        Person parsed = Json.fromJson(json, Person.class);
        System.out.println("Parsed record: " + parsed);

        JsonNode tree = Json.parseTree("{\"name\":\"Bob\",\"age\":25,\"tags\":[\"ops\"]}");
        System.out.println("Tree lookup: " + tree.get("name").asString() + " is " + tree.get("age").asInt());
    }
}
EOF
cat > src/test/java/com/example/json/JsonTest.java <<'EOF'
package com.example.json;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.List;

import org.junit.jupiter.api.Test;

import tools.jackson.core.JacksonException;
import tools.jackson.databind.JsonNode;

class JsonTest {

    @Test
    void roundTripsRecord() {
        Person original = new Person("Alice", 30, List.of("admin", "dev"));

        String json = Json.toJson(original);

        assertEquals("{\"name\":\"Alice\",\"age\":30,\"tags\":[\"admin\",\"dev\"]}", json);
        assertEquals(original, Json.fromJson(json, Person.class));
    }

    @Test
    void parsesTree() {
        JsonNode node = Json.parseTree("{\"a\":{\"b\":[1,2,3]}}");

        assertEquals(3, node.at("/a/b").size());
        assertEquals(2, node.at("/a/b/1").asInt());
    }

    @Test
    void rejectsMalformedJson() {
        assertThrows(JacksonException.class, () -> Json.parseTree("{not json"));
    }
}
